ALTER TABLE public.bookings ADD COLUMN starts_at timestamptz NOT NULL DEFAULT date_trunc('day', now()), ADD COLUMN ends_at timestamptz NOT NULL DEFAULT (date_trunc('day', now()) + interval '2 days'), ADD COLUMN dinner_choice text, ADD COLUMN guest_email text;
ALTER TABLE public.orders ADD COLUMN booking_id uuid;
ALTER TABLE public.rooms ADD COLUMN cleaning_booking_id uuid, ADD COLUMN exchange_towels boolean NOT NULL DEFAULT false;
CREATE TABLE public.invitation_emails (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.bookings(id), recipient text NOT NULL, subject text NOT NULL DEFAULT 'Velkommen til HotelPilot', created_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'simuleret');
GRANT ALL ON public.invitation_emails TO service_role;
ALTER TABLE public.invitation_emails ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.validate_stay() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.ends_at <= NEW.starts_at THEN RAISE EXCEPTION 'INVALID_STAY'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_booking_stay BEFORE INSERT OR UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.validate_stay();
CREATE OR REPLACE FUNCTION public.simulate_booking_invitation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.guest_email IS NOT NULL THEN INSERT INTO invitation_emails(booking_id,recipient) VALUES(NEW.id,NEW.guest_email); END IF; RETURN NEW; END $$;
CREATE TRIGGER booking_invitation AFTER INSERT ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.simulate_booking_invitation();
CREATE OR REPLACE FUNCTION public.require_guest(_token uuid,_device uuid,_require_started boolean DEFAULT true) RETURNS public.bookings LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN SELECT x.* INTO b FROM bookings x JOIN devices d ON d.booking_id=x.id WHERE x.access_token=_token AND d.id=_device; IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_LOGIN'; END IF; IF NOT b.active OR now()>=b.ends_at THEN RAISE EXCEPTION 'STAY_EXPIRED'; END IF; IF _require_started AND now()<b.starts_at THEN RAISE EXCEPTION 'STAY_NOT_STARTED'; END IF; RETURN b; END $$;
REVOKE ALL ON FUNCTION public.require_guest(uuid,uuid,boolean) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.guest_info(_b bookings,_device uuid) RETURNS json LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT json_build_object('access_token',_b.access_token,'device_id',_device,'guest_name',_b.guest_name,'room_number',_b.room_number,'reference',_b.reference,'capacity',r.capacity,'max_devices',r.capacity+2,'devices',(SELECT count(*) FROM devices d WHERE d.booking_id=_b.id),'housekeeping_status',CASE WHEN r.cleaning_booking_id=_b.id THEN r.housekeeping_status ELSE 'occupied' END,'wifi_ssid',CASE WHEN now()>=_b.starts_at AND now()<_b.ends_at AND _b.active THEN (SELECT value FROM hotel_secrets WHERE key='wifi_ssid') END,'wifi_password',CASE WHEN now()>=_b.starts_at AND now()<_b.ends_at AND _b.active THEN (SELECT value FROM hotel_secrets WHERE key='wifi_password') END,'starts_at',_b.starts_at,'ends_at',_b.ends_at,'server_now',now(),'dinner_choice',_b.dinner_choice) FROM rooms r WHERE r.number=_b.room_number $$;
REVOKE ALL ON FUNCTION public.guest_info(public.bookings,uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.register_device(public.bookings) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.guest_login(_reference text,_room text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN SELECT * INTO b FROM bookings WHERE upper(trim(reference))=upper(trim(_reference)) AND room_number=trim(_room) ORDER BY starts_at DESC LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_LOGIN'; END IF; IF NOT b.active OR now()>=b.ends_at THEN RAISE EXCEPTION 'STAY_EXPIRED'; END IF; RETURN guest_info(b,register_device(b)); END $$;
CREATE OR REPLACE FUNCTION public.guest_join(_token uuid) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN SELECT * INTO b FROM bookings WHERE access_token=_token; IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_LOGIN'; END IF; IF NOT b.active OR now()>=b.ends_at THEN RAISE EXCEPTION 'STAY_EXPIRED'; END IF; RETURN guest_info(b,register_device(b)); END $$;
CREATE OR REPLACE FUNCTION public.guest_session(_token uuid,_device uuid) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN b:=require_guest(_token,_device,false); RETURN guest_info(b,_device); END $$;
CREATE OR REPLACE FUNCTION public.guest_order(_token uuid,_device uuid,_type text,_details text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; _id uuid; BEGIN b:=require_guest(_token,_device); IF _type NOT IN ('towels','room_service') THEN RAISE EXCEPTION 'INVALID_ORDER'; END IF; INSERT INTO orders(room_number,booking_id,type,details) VALUES(b.room_number,b.id,_type,left(coalesce(_details,''),500)) RETURNING id INTO _id; RETURN _id; END $$;
CREATE OR REPLACE FUNCTION public.guest_set_housekeeping(_token uuid,_device uuid,_requested boolean) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; s text; BEGIN b:=require_guest(_token,_device); s:=CASE WHEN _requested THEN 'needs_cleaning' ELSE 'occupied' END; UPDATE rooms SET housekeeping_status=s,cleaning_booking_id=CASE WHEN _requested THEN b.id ELSE NULL END,exchange_towels=false,updated_at=now() WHERE number=b.room_number; RETURN s; END $$;
CREATE OR REPLACE FUNCTION public.guest_request_cleaning(_token uuid,_device uuid,_towels boolean) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN b:=require_guest(_token,_device); UPDATE rooms SET housekeeping_status='needs_cleaning',cleaning_booking_id=b.id,exchange_towels=_towels,updated_at=now() WHERE number=b.room_number; RETURN 'needs_cleaning'; END $$;
CREATE OR REPLACE FUNCTION public.guest_orders(_token uuid,_device uuid) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; result json; BEGIN b:=require_guest(_token,_device); SELECT coalesce(json_agg(q),'[]'::json) INTO result FROM (SELECT id,type,details,status,created_at FROM orders WHERE booking_id=b.id ORDER BY created_at DESC LIMIT 20) q; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.guest_cancel_order(_token uuid,_device uuid,_order uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN b:=require_guest(_token,_device); UPDATE orders SET status='cancelled' WHERE id=_order AND booking_id=b.id AND status IN ('pending','in_progress'); IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_CANCELLABLE'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.guest_dinner(_token uuid,_device uuid,_choice text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN b:=require_guest(_token,_device); IF _choice NOT IN ('hotel','out') THEN RAISE EXCEPTION 'INVALID_CHOICE'; END IF; UPDATE bookings SET dinner_choice=_choice WHERE id=b.id; END $$;
CREATE OR REPLACE FUNCTION public.guest_unlock(_token uuid,_device uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN b:=require_guest(_token,_device); RETURN 'Oplåsning simuleret · Værelse '||b.room_number; END $$;
CREATE OR REPLACE FUNCTION public.staff_set_room_status(_pin text,_room text,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT staff_check(_pin) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF _status NOT IN ('occupied','needs_cleaning','cleaning','clean') THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF; UPDATE rooms SET housekeeping_status=_status,updated_at=now(),cleaning_booking_id=CASE WHEN _status='occupied' THEN NULL ELSE cleaning_booking_id END,exchange_towels=CASE WHEN _status='occupied' THEN false ELSE exchange_towels END WHERE number=_room; END $$;
CREATE OR REPLACE FUNCTION public.staff_set_order_status(_pin text,_order uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT staff_check(_pin) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF _status NOT IN ('pending','in_progress','done') THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF; UPDATE orders SET status=_status WHERE id=_order AND status NOT IN ('cancelled','done'); END $$;
CREATE OR REPLACE FUNCTION public.staff_pms(_pin text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT staff_check(_pin) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; RETURN json_build_object('bookings',(SELECT coalesce(json_agg(q),'[]'::json) FROM (SELECT id,reference,room_number,guest_name,guest_email,starts_at,ends_at,active,dinner_choice FROM bookings ORDER BY starts_at DESC) q),'emails',(SELECT coalesce(json_agg(q),'[]'::json) FROM (SELECT e.id,e.recipient,e.subject,e.status,e.created_at,b.reference FROM invitation_emails e JOIN bookings b ON b.id=e.booking_id ORDER BY e.created_at DESC LIMIT 30) q)); END $$;
CREATE OR REPLACE FUNCTION public.staff_mock_booking(_pin text,_name text,_email text,_room text,_start timestamptz,_end timestamptz) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ref text; BEGIN IF NOT staff_check(_pin) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF trim(_name)='' OR _email NOT LIKE '%@%.%' THEN RAISE EXCEPTION 'INVALID_BOOKING'; END IF; IF EXISTS(SELECT 1 FROM bookings WHERE room_number=_room AND active AND starts_at<_end AND ends_at>_start) THEN RAISE EXCEPTION 'ROOM_BUSY'; END IF; ref:='HP-'||upper(substr(gen_random_uuid()::text,1,8)); INSERT INTO bookings(reference,room_number,guest_name,guest_email,starts_at,ends_at) VALUES(ref,_room,left(trim(_name),100),left(_email,200),_start,_end); RETURN ref; END $$;
GRANT EXECUTE ON FUNCTION public.guest_request_cleaning(uuid,uuid,boolean),public.guest_orders(uuid,uuid),public.guest_cancel_order(uuid,uuid,uuid),public.guest_dinner(uuid,uuid,text),public.guest_unlock(uuid,uuid),public.staff_pms(text),public.staff_mock_booking(text,text,text,text,timestamptz,timestamptz) TO anon,authenticated;
REVOKE ALL ON FUNCTION public.simulate_booking_invitation(),public.validate_stay() FROM PUBLIC,anon,authenticated;